using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Web.Script.Serialization;
using System.Xml.Linq;
using Microsoft.VisualBasic.FileIO;

namespace Aurora {
public sealed class OuORelease {
    public string Tag,Name,Notes,Page,Download,Digest,AssetName;public Version Version;public bool Preview;public long Bytes;
    public override string ToString(){return Name+" • "+(Preview?L.T("Prévia de testes","Test preview"):L.T("Estável","Stable"));}
}
public static class OuOUpdates {
    public const string Repository="https://github.com/CarvalhoRonan/OuO";
    public const string ReleasesApi="https://api.github.com/repos/CarvalhoRonan/OuO/releases?per_page=30";
    public static Version Current{get{return new Version(System.Diagnostics.FileVersionInfo.GetVersionInfo(System.Reflection.Assembly.GetExecutingAssembly().Location).FileVersion);}}
    public static string Folder{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AuroraUtility","Updates");}}
    public static bool TrustedDownload(string address){Uri uri;return Uri.TryCreate(address,UriKind.Absolute,out uri)&&uri.Scheme=="https"&&uri.Host.Equals("github.com",StringComparison.OrdinalIgnoreCase)&&uri.IsDefaultPort&&uri.AbsolutePath.StartsWith("/CarvalhoRonan/OuO/releases/download/",StringComparison.Ordinal)&&String.IsNullOrEmpty(uri.UserInfo)&&String.IsNullOrEmpty(uri.Query)&&!uri.AbsolutePath.Contains("..");}
    static string Value(Dictionary<string,object> item,string key){object value;return item.TryGetValue(key,out value)?Convert.ToString(value,CultureInfo.InvariantCulture):"";}
    public static OuORelease[] Parse(string json,bool includePreview){var list=new List<OuORelease>();var parsed=new JavaScriptSerializer{MaxJsonLength=4*1024*1024}.DeserializeObject(json) as object[];if(parsed==null)throw new InvalidDataException("Invalid GitHub release list");foreach(var entry in parsed){var r=entry as Dictionary<string,object>;if(r==null)continue;bool draft=Value(r,"draft").Equals("True",StringComparison.OrdinalIgnoreCase),preview=Value(r,"prerelease").Equals("True",StringComparison.OrdinalIgnoreCase);if(draft||preview&&!includePreview)continue;string tag=Value(r,"tag_name");var match=Regex.Match(tag,@"^v?(\d+\.\d+\.\d+(?:\.\d+)?)(?:[-+].*)?$");Version version;if(!match.Success||!Version.TryParse(match.Groups[1].Value,out version))continue;version=new Version(version.Major,version.Minor,Math.Max(0,version.Build),Math.Max(0,version.Revision));object assetsValue;if(!r.TryGetValue("assets",out assetsValue))continue;var assets=assetsValue as object[];if(assets==null)continue;foreach(var asset in assets.OfType<Dictionary<string,object>>()){string name=Value(asset,"name"),url=Value(asset,"browser_download_url"),digest=Value(asset,"digest");long bytes;if(!name.StartsWith("OuO-",StringComparison.OrdinalIgnoreCase)||!name.EndsWith(".zip",StringComparison.OrdinalIgnoreCase)||!TrustedDownload(url)||!Int64.TryParse(Value(asset,"size"),out bytes)||bytes<=0||bytes>1073741824)continue;if(!Regex.IsMatch(digest,@"^sha256:[a-f0-9]{64}$",RegexOptions.IgnoreCase))continue;string page=Value(r,"html_url");if(!page.StartsWith(Repository+"/releases/tag/",StringComparison.Ordinal))continue;list.Add(new OuORelease{Tag=tag,Name=Value(r,"name"),Notes=Value(r,"body"),Page=page,Version=version,Preview=preview,Download=url,Digest=digest.Substring(7),AssetName=Path.GetFileName(name),Bytes=bytes});break;}}
        return list.OrderByDescending(x=>x.Version).ThenBy(x=>x.Preview).ToArray();}
    static HttpWebRequest Request(string address){ServicePointManager.SecurityProtocol|=(SecurityProtocolType)3072;var request=(HttpWebRequest)WebRequest.Create(address);request.Timeout=12000;request.ReadWriteTimeout=15000;request.UserAgent="OuO/1.1 (official release check)";request.Accept="application/vnd.github+json";return request;}
    public static OuORelease[] Check(bool includePreview){using(var response=(HttpWebResponse)Request(ReleasesApi).GetResponse())using(var reader=new StreamReader(response.GetResponseStream(),Encoding.UTF8)){var json=reader.ReadToEnd();if(json.Length>4*1024*1024)throw new InvalidDataException("Release response too large");return Parse(json,includePreview);}}
    public static string Prepare(OuORelease release,Action<WorkProgress> progress,CancellationToken cancel){
        if(release==null||!TrustedDownload(release.Download)||!Regex.IsMatch(release.Digest??"","^[a-fA-F0-9]{64}$"))throw new InvalidDataException("Untrusted update metadata");Directory.CreateDirectory(Folder);string destination=Path.Combine(Folder,"download-"+Guid.NewGuid().ToString("N")+".zip");string partial=destination+".part";
        try{long received=0;using(var response=(HttpWebResponse)Request(release.Download).GetResponse())using(var input=response.GetResponseStream())using(var output=new FileStream(partial,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] buffer=new byte[65536];int count;var throttle=System.Diagnostics.Stopwatch.StartNew();while((count=input.Read(buffer,0,buffer.Length))>0){cancel.ThrowIfCancellationRequested();received+=count;if(received>release.Bytes)throw new InvalidDataException("Download exceeded the published size");output.Write(buffer,0,count);if(progress!=null&&throttle.ElapsedMilliseconds>=150){progress(new WorkProgress{Stage=L.T("Baixando OuO","Downloading OuO"),Done=received,Total=release.Bytes,Bytes=true});throttle.Restart();}}}if(received!=release.Bytes)throw new InvalidDataException("Incomplete update download");using(var sha=SHA256.Create())using(var stream=File.OpenRead(partial)){string actual=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");if(!actual.Equals(release.Digest,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException(L.T("A integridade do download não foi confirmada.","The download integrity check failed."));}cancel.ThrowIfCancellationRequested();File.Move(partial,destination);
            BackupCurrent(progress,cancel);
            string stage=Path.Combine(Folder,"prepared-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);Extract(destination,stage,progress,cancel);return stage;
        }catch{if(File.Exists(partial))File.Delete(partial);throw;}
    }
    public static void Extract(string archivePath,string destination,Action<WorkProgress> progress,CancellationToken cancel){
        string root=Path.GetFullPath(destination).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
        using(var archive=ZipFile.OpenRead(archivePath)){if(archive.Entries.Count==0||archive.Entries.Count>12000||archive.Entries.Sum(x=>x.Length)>2147483648L)throw new InvalidDataException("Invalid update archive size");var targets=new List<Tuple<ZipArchiveEntry,string>>();var unique=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var entry in archive.Entries){string name=entry.FullName.Replace('/',Path.DirectorySeparatorChar);if(name.IndexOf(':')>=0||Path.IsPathRooted(name)||name.Split(Path.DirectorySeparatorChar).Any(x=>x==".."||x=="."||x.TrimEnd(' ','.')!=x))throw new InvalidDataException("Invalid update entry");string target=Path.GetFullPath(Path.Combine(root,name));if(!target.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!unique.Add(target))throw new InvalidDataException("Duplicate or escaping update entry");if((entry.ExternalAttributes>>16&0xf000)==0xa000)throw new InvalidDataException("Symbolic links are not accepted in updates");targets.Add(Tuple.Create(entry,target));}int done=0;foreach(var target in targets){cancel.ThrowIfCancellationRequested();if(target.Item1.FullName.EndsWith("/"))Directory.CreateDirectory(target.Item2);else{Directory.CreateDirectory(Path.GetDirectoryName(target.Item2));using(var source=target.Item1.Open())using(var output=new FileStream(target.Item2,FileMode.CreateNew,FileAccess.Write,FileShare.None)){source.CopyTo(output);}}if(progress!=null)progress(new WorkProgress{Stage=L.T("Preparando arquivos","Preparing files"),Done=++done,Total=targets.Count});}}
    }
    static void BackupCurrent(Action<WorkProgress> progress,CancellationToken cancel){string basePath=AppDomain.CurrentDomain.BaseDirectory,manifest=Path.Combine(basePath,"ARQUIVOS-SHA256.csv");if(!File.Exists(manifest))throw new FileNotFoundException(L.T("O manifesto da instalação atual está ausente; a atualização não substituirá esta versão.","The current installation manifest is missing; this version will not be replaced."));var paths=new List<string>();using(var csv=new TextFieldParser(manifest,Encoding.UTF8)){csv.TextFieldType=FieldType.Delimited;csv.SetDelimiters(",");csv.HasFieldsEnclosedInQuotes=true;csv.ReadFields();while(!csv.EndOfData){var fields=csv.ReadFields();if(fields!=null&&fields.Length>0)paths.Add(fields[0]);}}
        string root=Path.GetFullPath(basePath).TrimEnd('\\')+"\\";var valid=new List<Tuple<string,string>>();foreach(string relative in paths){string path=Path.GetFullPath(Path.Combine(root,relative.Replace('/',Path.DirectorySeparatorChar)));if(!path.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!File.Exists(path)||(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Invalid backup manifest entry");valid.Add(Tuple.Create(path,relative.Replace('\\','/')));}valid.Add(Tuple.Create(manifest,"ARQUIVOS-SHA256.csv"));string outputPath=Path.Combine(Folder,"previous-"+Current+"-"+Guid.NewGuid().ToString("N")+".zip");using(var archive=ZipFile.Open(outputPath,ZipArchiveMode.Create)){int done=0;foreach(var file in valid){cancel.ThrowIfCancellationRequested();archive.CreateEntryFromFile(file.Item1,file.Item2,CompressionLevel.Fastest);if(progress!=null)progress(new WorkProgress{Stage=L.T("Guardando a versão anterior","Backing up the previous version"),Done=++done,Total=valid.Count});}}
    }
}
}
